static bool parse_sdp_response(const unsigned char* data, size_t len,
                               std::string& secc_ip, int& secc_port,
                               std::string& /*iface*/)
{
    // SDP Response structure (ISO 15118-4):
    //  0:       0x01 (SDP response marker)
    //  1-3:     0xFE, 0x90, 0x01 (SDP response type)
    //  4-7:     payload length (uint32 big-endian) -- always 20
    //  8-23:    SECC IPv6 address (16 bytes)
    // 24-25:    SECC TCP port (uint16 big-endian)
    // 26-27:    Transport protocol (0x1000 = TCP)
    if (len < 28) return false;
    if (data[0] != 0x01) return false;
    if (data[1] != 0xFE || data[2] != 0x90 || data[3] != 0x01) return false;

    char ipv6_str[INET6_ADDRSTRLEN];
    struct in6_addr addr;
    memcpy(&addr, data + 8, 16);
    if (inet_ntop(AF_INET6, &addr, ipv6_str, sizeof(ipv6_str)) == NULL) return false;

    uint16_t port_be;
    memcpy(&port_be, data + 24, 2);
    uint16_t tcp_port = (uint16_t)((port_be >> 8) | (port_be << 8));

    secc_ip = ipv6_str;
    secc_port = tcp_port;
    return true;
}

