void V2G__UDP__SDP__Port::user_start()
{
    if (udp_sock >= 0) return;

    udp_sock = socket(AF_INET6, SOCK_DGRAM, 0);
    if (udp_sock < 0) return;

    int reuse = 1;
    setsockopt(udp_sock, SOL_SOCKET, SO_REUSEADDR, &reuse, sizeof(reuse));

    struct sockaddr_in6 bind_addr = {};
    bind_addr.sin6_family = AF_INET6;
    bind_addr.sin6_port = 0;
    bind_addr.sin6_addr = in6addr_any;

    if (!network_interface.empty()) {
        unsigned int ifidx = if_nametoindex(network_interface.c_str());
        if (ifidx != 0) bind_addr.sin6_scope_id = ifidx;
    }

    bind(udp_sock, (struct sockaddr*)&bind_addr, sizeof(bind_addr));

    if (!ipv6_multicast.empty() && !network_interface.empty()) {
        struct ipv6_mreq mreq = {};
        if (inet_pton(AF_INET6, ipv6_multicast.c_str(), &mreq.ipv6mr_multiaddr) > 0) {
            unsigned int ifidx = if_nametoindex(network_interface.c_str());
            mreq.ipv6mr_interface = ifidx;
            setsockopt(udp_sock, IPPROTO_IPV6, IPV6_ADD_MEMBERSHIP, &mreq, sizeof(mreq));
        }
    }

    Handler_Add_Fd_Read(udp_sock);
}

